public class MapNode {
 public string Id=Guid.NewGuid().ToString(),DeviceId="",Name="",Kind="Device";
 public float X,Y;public float Width=178,Height=56;
}
public class MapPoint {public float X,Y;}
public class MapLink {
 public string FromSide="",ToSide="";public int FromOrder=-1,ToOrder=-1;public List<MapPoint> ManualRoute=new List<MapPoint>();
 public string Id=Guid.NewGuid().ToString(),From,To,FromPort="",ToPort="",Kind="Cable";
}
public class NetworkMap {
 public List<MapNode> Nodes=new List<MapNode>();public List<MapLink> Links=new List<MapLink>();
 public string Encode(){return new JavaScriptSerializer().Serialize(this);}
 public static NetworkMap Decode(string json){var m=new JavaScriptSerializer().Deserialize<NetworkMap>(json);if(m==null||m.Nodes==null||m.Links==null||m.Nodes.Count>1000||m.Links.Count>3000)throw new Exception("Invalid layout.");var ids=new HashSet<string>();foreach(var n in m.Nodes){if(n==null||String.IsNullOrEmpty(n.Id)||!ids.Add(n.Id)||float.IsNaN(n.X)||float.IsInfinity(n.X)||float.IsNaN(n.Y)||float.IsInfinity(n.Y)||Math.Abs(n.X)>100000||Math.Abs(n.Y)>100000)throw new Exception("Invalid layout node.");if(float.IsNaN(n.Width)||float.IsInfinity(n.Width)||float.IsNaN(n.Height)||float.IsInfinity(n.Height)||n.Width<178||n.Width>2000||n.Height<56||n.Height>2000)throw new Exception("Invalid node size.");n.Name=n.Name??"";n.DeviceId=n.DeviceId??"";}var links=new HashSet<string>();foreach(var l in m.Links)if(l==null||!links.Add(l.Id)||!ids.Contains(l.From)||!ids.Contains(l.To)||l.From==l.To||!(l.Kind=="Cable"||l.Kind=="Wi-Fi"))throw new Exception("Invalid layout link.");foreach(var l in m.Links){if(!new[]{"","Top","Right","Bottom","Left"}.Contains(l.FromSide)||!new[]{"","Top","Right","Bottom","Left"}.Contains(l.ToSide)||l.FromOrder< -1||l.ToOrder< -1||l.FromOrder>3000||l.ToOrder>3000||l.ManualRoute==null||l.ManualRoute.Count>1000||l.ManualRoute.Any(p=>p==null||float.IsNaN(p.X)||float.IsInfinity(p.X)||float.IsNaN(p.Y)||float.IsInfinity(p.Y)||Math.Abs(p.X)>100000||Math.Abs(p.Y)>100000))throw new Exception("Invalid manual cable layout.");for(int i=1;i<l.ManualRoute.Count;i++)if(l.ManualRoute[i].X!=l.ManualRoute[i-1].X&&l.ManualRoute[i].Y!=l.ManualRoute[i-1].Y)throw new Exception("Cable segments must be horizontal or vertical.");}return m;}
}
public class LinkEditor:Form {
 public string FromPort,ToPort,Kind;
 public LinkEditor(MapLink link,string from,string to){Text="Link — "+from+" to "+to;ClientSize=new Size(440,255);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;MinimizeBox=false;StartPosition=FormStartPosition.CenterParent;BackColor=Dashboard.Bg;ForeColor=Dashboard.Ink;Font=new Font("Segoe UI",10);var a=EditControls.Text(this,"From port (e.g. LAN 1)",20,18,190,link.FromPort);var b=EditControls.Text(this,"To port (e.g. WAN)",230,18,190,link.ToPort);Ui.Label(this,"Connection type",20,95,260,22,Dashboard.Ink);var type=new ComboBox{Location=new Point(20,123),Width=400,DropDownStyle=ComboBoxStyle.DropDownList};type.Items.AddRange(new[]{"Cable","Wi-Fi"});type.SelectedItem=link.Kind;Controls.Add(type);var save=Dashboard.Btn("Save",()=>{FromPort=a.Text.Trim();ToPort=b.Text.Trim();Kind=type.Text;DialogResult=DialogResult.OK;});save.Location=new Point(235,198);Controls.Add(save);var cancel=Dashboard.Btn("Cancel",()=>DialogResult=DialogResult.Cancel);cancel.Location=new Point(330,198);Controls.Add(cancel);CancelButton=cancel;AcceptButton=save;}
}
public class TopologyView:UserControl {
 public TopologyCanvas Canvas;ListBox palette;TextBox query;Label state;Func<List<Device>> devices;
 public TopologyView(Func<List<Device>> source,Action<Device> open,bool testing,NetworkMap network=null,Action changed=null){devices=source;Dock=DockStyle.Fill;BackColor=Dashboard.Bg;var left=new Panel{Dock=DockStyle.Left,Width=235,Padding=new Padding(0,0,12,0)};Controls.Add(left);Ui.Label(left,"Network Devices",4,4,220,27,Dashboard.Accent,11,true);query=new TextBox{Location=new Point(4,36),Width=215,BackColor=Dashboard.PanelBg,ForeColor=Dashboard.Ink};left.Controls.Add(query);palette=new ListBox{Location=new Point(4,74),Width=215,Height=260,Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Bottom,BackColor=Dashboard.PanelBg,ForeColor=Dashboard.Ink,BorderStyle=BorderStyle.None,DisplayMember="Name"};left.Controls.Add(palette);var other=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=142,FlowDirection=FlowDirection.TopDown,WrapContents=false};other.Controls.Add(new Label{Text="Other Networking",ForeColor=Dashboard.Accent,AutoSize=true});foreach(var kind in new[]{"WAN / ISP","Patch panel","Other node"}){string k=kind;other.Controls.Add(Dashboard.Btn("+ "+kind,()=>AddOther(k)));}left.Controls.Add(other);left.Resize+=(s,e)=>palette.Height=Math.Max(60,left.Height-230);query.TextChanged+=(s,e)=>RefreshDevices();palette.DrawMode=DrawMode.OwnerDrawFixed;palette.ItemHeight=30;palette.DrawItem+=(s,e)=>{if(e.Index<0)return;e.DrawBackground();var d=(Device)palette.Items[e.Index];using(var image=DeviceImages.Read(d.IconData)){if(image!=null)e.Graphics.DrawImage(image,e.Bounds.X+3,e.Bounds.Y+3,24,24);}TextRenderer.DrawText(e.Graphics,d.Name,palette.Font,new Rectangle(e.Bounds.X+32,e.Bounds.Y,e.Bounds.Width-32,e.Bounds.Height),Dashboard.Ink,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);};palette.MouseDown+=(s,e)=>{int i=palette.IndexFromPoint(e.Location);if(e.Button==MouseButtons.Left&&i>=0){palette.SelectedIndex=i;palette.DoDragDrop("device:"+((Device)palette.Items[i]).Id,DragDropEffects.Copy);}};
  var right=new Panel{Dock=DockStyle.Fill};Controls.Add(right);right.BringToFront();var tools=new FlowLayoutPanel{Dock=DockStyle.Top,Height=40,WrapContents=false};tools.Controls.Add(new Label{Text="Network Topology",ForeColor=Dashboard.Accent,Width=155,Height=30,TextAlign=ContentAlignment.MiddleLeft});tools.Controls.Add(Dashboard.Btn("Fit",()=>Canvas.Fit()));tools.Controls.Add(Dashboard.Btn("Undo",()=>Canvas.Undo()));tools.Controls.Add(Dashboard.Btn("Export",()=>{using(var f=new SaveFileDialog{Filter="Layout JSON|*.json",FileName="homelab-layout.json"})if(f.ShowDialog(this)==DialogResult.OK)try{File.WriteAllText(f.FileName,Canvas.Map.Encode());}catch(Exception ex){MessageBox.Show(ex.Message);}}));right.Controls.Add(tools);var hint=new Label{Dock=DockStyle.Bottom,Height=43,ForeColor=Dashboard.Muted,Text="Drag devices onto the canvas. Drag any socket to another node to link.\r\nSelect cable: drag square handles to route, round ends to reorder · Shift + socket: new link"};right.Controls.Add(hint);state=new Label{Dock=DockStyle.Bottom,Height=24,ForeColor=Dashboard.Accent};right.Controls.Add(state);Canvas=new TopologyCanvas(source,open,testing?null:Path.Combine(Config.Folder,"layout-v1.json"),x=>state.Text=x);if(network!=null){Canvas.Map=network;Canvas.Changed=changed;Canvas.Invalidate();state.Text=network.Nodes.Count==0?"Start by dragging a device from the palette.":"Layout loaded · solid Cable / dotted Wi-Fi";}right.Controls.Add(Canvas);Canvas.BringToFront();RefreshDevices();
 }
 public void RefreshDevices(){if(palette==null)return;palette.Items.Clear();foreach(var d in devices().Where(d=>(d.Name+" "+d.Group).IndexOf(query.Text,StringComparison.OrdinalIgnoreCase)>=0).OrderBy(d=>d.Name))palette.Items.Add(d);if(Canvas!=null)Canvas.Invalidate();}
 void AddOther(string kind){using(var f=new Form{Text="Add "+kind,ClientSize=new Size(370,155),StartPosition=FormStartPosition.CenterParent,BackColor=Dashboard.Bg,ForeColor=Dashboard.Ink,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false}){var name=EditControls.Text(f,"Name",15,15,340,kind);var add=Dashboard.Btn("Add",()=>{if(String.IsNullOrWhiteSpace(name.Text))return;f.DialogResult=DialogResult.OK;});add.Location=new Point(190,102);f.Controls.Add(add);var cancel=Dashboard.Btn("Cancel",()=>f.DialogResult=DialogResult.Cancel);cancel.Location=new Point(280,102);f.Controls.Add(cancel);f.AcceptButton=add;f.CancelButton=cancel;if(f.ShowDialog(this)==DialogResult.OK)Canvas.AddNode("",name.Text.Trim(),kind,Canvas.World(new Point(Canvas.Width/2,Canvas.Height/2)));}}
}
public class TopologyCanvas:Control {
 public string SelectedDeviceId{get{return selected==null?null:selected.DeviceId;}}
 public Action Changed;public void ReportSaved(){status("Network saved · "+Map.Nodes.Count+" nodes · "+Map.Links.Count+" links");}
 public NetworkMap Map=new NetworkMap();public float ZoomScale=1;public PointF Pan=new PointF(25,25);
 readonly Func<List<Device>> devices;readonly Action<Device> open;readonly string path;readonly Action<string> status;readonly Stack<string> undo=new Stack<string>();readonly ContextMenuStrip menu=new ContextMenuStrip();
 MapLink editingCable;bool editingEnd,endFrom;int editingSegment;PointF[] originalRoute;Point dragOrigin;
 Dictionary<string,PointF[]> routes;string dragSide;MapNode moving,resizing,linkStart,selected;MapLink selectedLink;Point last;PointF offset,wire;string before;bool panning,locked;
 public TopologyCanvas(Func<List<Device>> source,Action<Device> openDevice,string file,Action<string> report){devices=source;open=openDevice;path=file;status=report;Dock=DockStyle.Fill;BackColor=Dashboard.PanelBg;ForeColor=Dashboard.Ink;DoubleBuffered=true;AllowDrop=true;TabStop=true;SetStyle(ControlStyles.Selectable,true);if(path!=null&&File.Exists(path))try{Map=NetworkMap.Decode(File.ReadAllText(path));}catch(Exception ex){locked=true;status("Layout could not be read; original preserved. "+ex.Message);}if(!locked)status(Map.Nodes.Count==0?"Start by dragging a device from the palette.":"Layout loaded · solid Cable / dotted Wi-Fi");DragEnter+=(s,e)=>{if(!locked&&e.Data.GetDataPresent(DataFormats.Text)&&((string)e.Data.GetData(DataFormats.Text)).StartsWith("device:"))e.Effect=DragDropEffects.Copy;};DragDrop+=(s,e)=>{var id=((string)e.Data.GetData(DataFormats.Text)).Substring(7);var d=devices().FirstOrDefault(x=>x.Id==id);if(d!=null)AddNode(d.Id,d.Name,"Device",World(PointToClient(new Point(e.X,e.Y))));};}
 public PointF World(Point p){return new PointF((p.X-Pan.X)/ZoomScale,(p.Y-Pan.Y)/ZoomScale);}
 RectangleF Box(MapNode n){return new RectangleF(n.X,n.Y,n.Width,n.Height);}PointF Socket(MapNode n,bool bottom){return new PointF(n.X+n.Width/2,n.Y+(bottom?n.Height:0));}
 string NodeName(MapNode n){var d=devices().FirstOrDefault(x=>x.Id==n.DeviceId);return d!=null?d.Name:n.Name+(n.DeviceId.Length>0?" (missing)":"");}
 public void AddNode(string id,string name,string kind,PointF p){if(locked)return;var existing=Map.Nodes.FirstOrDefault(n=>id.Length>0&&n.DeviceId==id);if(existing!=null){selected=existing;Pan=new PointF(Width/2-(existing.X+existing.Width/2)*ZoomScale,Height/2-(existing.Y+existing.Height/2)*ZoomScale);Invalidate();status("Device is already on the layout.");return;}Remember();Map.Nodes.Add(new MapNode{DeviceId=id,Name=name,Kind=kind,X=p.X,Y=p.Y});Save();}
 void Remember(){undo.Push(Map.Encode());}
 public void Undo(){if(editingCable!=null){CancelCableDrag();return;}if(locked||undo.Count==0)return;Map=NetworkMap.Decode(undo.Pop());selected=null;selectedLink=null;Save();}
 void Save(){Invalidate();try{NetworkMap.Decode(Map.Encode());if(path!=null){Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path+".tmp",Map.Encode());if(File.Exists(path))File.Replace(path+".tmp",path,path+".bak");else File.Move(path+".tmp",path);}if(Changed!=null)Changed();status((Changed==null?"Saved":"Unsaved changes — Menu > Save")+" · "+Map.Nodes.Count+" nodes · "+Map.Links.Count+" links");}catch(Exception ex){status("Not saved: "+ex.Message);}}
 public void SetZoom(int percent){var center=new Point(Width/2,Height/2);var w=World(center);ZoomScale=percent/100f;Pan=new PointF(center.X-w.X*ZoomScale,center.Y-w.Y*ZoomScale);Invalidate();}
 public void Fit(){if(Map.Nodes.Count==0){Pan=new PointF(25,25);Invalidate();return;}float x=Map.Nodes.Min(n=>n.X),y=Map.Nodes.Min(n=>n.Y),w=Map.Nodes.Max(n=>n.X+n.Width)-x,h=Map.Nodes.Max(n=>n.Y+n.Height)-y;ZoomScale=Math.Max(.2f,Math.Min(1.5f,Math.Min((Width-60)/w,(Height-70)/h)));Pan=new PointF((Width-w*ZoomScale)/2-x*ZoomScale,(Height-h*ZoomScale)/2-y*ZoomScale);Invalidate();if(ZoomChanged!=null)ZoomChanged((int)Math.Round(ZoomScale*100));}
 public Action<int> ZoomChanged;
 protected override void OnInvalidated(InvalidateEventArgs e){routes=null;base.OnInvalidated(e);}
 PointF[] Route(MapLink l){if(routes==null)routes=MapRouting.Build(Map);return routes[l.Id];}
 string SocketHit(MapNode n,PointF p){foreach(var side in new[]{"Top","Right","Bottom","Left"}){var q=MapRouting.Socket(n,side);if(Math.Abs(p.X-q.X)<=9/ZoomScale&&Math.Abs(p.Y-q.Y)<=9/ZoomScale)return side;}return null;}
 void PortLabel(Graphics g,string text,PointF p,string side,Font font,Brush ink){if(String.IsNullOrEmpty(text))return;var size=g.MeasureString(text,font);float x=p.X+5,y=p.Y+5;if(side=="Left"){x=p.X-size.Width-7;y=p.Y-19;}if(side=="Right"){x=p.X+7;y=p.Y-19;}if(side=="Top"){x=p.X+5;y=p.Y-22;}using(var bg=new SolidBrush(BackColor))g.FillRectangle(bg,x,y,size.Width,size.Height);g.DrawString(text,font,ink,x,y);}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.TranslateTransform(Pan.X,Pan.Y);g.ScaleTransform(ZoomScale,ZoomScale);using(var line=new Pen(Color.FromArgb(41,51,65),1/ZoomScale)){var tl=World(Point.Empty);var br=World(new Point(Width,Height));for(float x=(float)Math.Floor(tl.X/30)*30;x<br.X;x+=30)for(float y=(float)Math.Floor(tl.Y/30)*30;y<br.Y;y+=30)g.DrawLine(line,x,y,x+1,y);}
  using(var font=new Font("Segoe UI",9))using(var ink=new SolidBrush(Dashboard.Ink))foreach(var l in Map.Links){var pts=Route(l);using(var halo=new Pen(BackColor,6))g.DrawLines(halo,pts);using(var pen=new Pen(l==selectedLink?Dashboard.Accent:Color.FromArgb(47,148,177),2)){if(l.Kind=="Wi-Fi")pen.DashStyle=DashStyle.Dot;g.DrawLines(pen,pts);using(var socket=new SolidBrush(Dashboard.Accent)){foreach(var end in new[]{pts[0],pts[pts.Length-1]})g.FillEllipse(socket,end.X-4,end.Y-4,8,8);}}var from=Map.Nodes.First(n=>n.Id==l.From);var to=Map.Nodes.First(n=>n.Id==l.To);PortLabel(g,l.FromPort,pts[0],MapRouting.SideAt(Map,l,l.From),font,ink);PortLabel(g,l.ToPort,pts[pts.Length-1],MapRouting.SideAt(Map,l,l.To),font,ink);}
  if(linkStart!=null)using(var pen=new Pen(Dashboard.Accent,2)){g.DrawLine(pen,MapRouting.Socket(linkStart,dragSide),wire);}
  using(var font=new Font("Segoe UI",10,FontStyle.Bold))using(var small=new Font("Segoe UI",8))using(var ink=new SolidBrush(Dashboard.Ink))using(var muted=new SolidBrush(Dashboard.Muted))foreach(var n in Map.Nodes){using(var bg=new SolidBrush(Color.FromArgb(40,83,92)))g.FillRectangle(bg,Box(n));using(var border=new Pen(n==selected?Dashboard.Accent:Color.FromArgb(53,104,118),n==selected?2:1))g.DrawRectangle(border,n.X,n.Y,n.Width,n.Height);var d=devices().FirstOrDefault(x=>x.Id==n.DeviceId);using(var sf=new StringFormat{Trimming=StringTrimming.EllipsisCharacter,FormatFlags=StringFormatFlags.NoWrap}){g.DrawString(NodeName(n),font,ink,new RectangleF(n.X+9,n.Y+8,n.Width-50,23),sf);g.DrawString(d==null?n.Kind:Ui.Detail(d,"Device type"),small,muted,new RectangleF(n.X+9,n.Y+33,n.Width-33,20),sf);}if(d!=null)using(var image=DeviceImages.Read(d.IconData)){if(image!=null)g.DrawImage(image,n.X+n.Width-35,n.Y+10,28,28);}using(var grip=new Pen(Dashboard.Accent,1/ZoomScale)){for(int k=4;k<=12;k+=4)g.DrawLine(grip,n.X+n.Width-k,n.Y+n.Height-2,n.X+n.Width-2,n.Y+n.Height-k);}foreach(string side in new[]{"Top","Right","Bottom","Left"}){var p=MapRouting.Socket(n,side);using(var fill=new SolidBrush(Dashboard.Accent))g.FillEllipse(fill,p.X-5,p.Y-5,10,10);}}
  if(selectedLink!=null&&Map.Links.Contains(selectedLink)){var pts=Route(selectedLink);using(var pen=new Pen(Dashboard.Accent,3)){if(selectedLink.Kind=="Wi-Fi")pen.DashStyle=DashStyle.Dot;g.DrawLines(pen,pts);}using(var fill=new SolidBrush(Dashboard.Accent))using(var outline=new Pen(BackColor,1)){for(int i=0;i<pts.Length-1;i++){var q=new PointF((pts[i].X+pts[i+1].X)/2,(pts[i].Y+pts[i+1].Y)/2);float size=7/ZoomScale;g.FillRectangle(fill,q.X-size/2,q.Y-size/2,size,size);g.DrawRectangle(outline,q.X-size/2,q.Y-size/2,size,size);}foreach(var q in new[]{pts[0],pts[pts.Length-1]}){float size=12/ZoomScale;g.FillEllipse(fill,q.X-size/2,q.Y-size/2,size,size);g.DrawEllipse(outline,q.X-size/2,q.Y-size/2,size,size);}}}
  if(Map.Nodes.Count==0){g.ResetTransform();TextRenderer.DrawText(g,"Drag a device here to start your network layout",Font,new Rectangle(30,55,Width-60,80),Dashboard.Muted,TextFormatFlags.HorizontalCenter|TextFormatFlags.WordBreak);}
 }
 bool ResizeHit(MapNode n,PointF p){float size=14/ZoomScale;return p.X>=n.X+n.Width-size&&p.X<=n.X+n.Width+3/ZoomScale&&p.Y>=n.Y+n.Height-size&&p.Y<=n.Y+n.Height+3/ZoomScale;}
 MapNode Hit(PointF p){return Map.Nodes.LastOrDefault(n=>Box(n).Contains(p)||SocketHit(n,p)!=null||ResizeHit(n,p));}
 MapLink HitLink(PointF p){return Map.Links.LastOrDefault(l=>{var a=Route(l);for(int i=1;i<a.Length;i++){float dx=a[i].X-a[i-1].X,dy=a[i].Y-a[i-1].Y;float t=dx*dx+dy*dy==0?0:Math.Max(0,Math.Min(1,((p.X-a[i-1].X)*dx+(p.Y-a[i-1].Y)*dy)/(dx*dx+dy*dy)));if(Math.Pow(p.X-a[i-1].X-t*dx,2)+Math.Pow(p.Y-a[i-1].Y-t*dy,2)<64/(ZoomScale*ZoomScale))return true;}return false;});}
 void CancelCableDrag(){if(editingCable==null)return;Map=NetworkMap.Decode(before);editingCable=null;selectedLink=null;Capture=false;Invalidate();status("Cable adjustment cancelled.");}
 protected override void OnMouseCaptureChanged(EventArgs e){base.OnMouseCaptureChanged(e);if(!Capture&&editingCable!=null)CancelCableDrag();}
 bool CableHandle(PointF p){if(selectedLink==null||!Map.Links.Contains(selectedLink))return false;var pts=Route(selectedLink);float tolerance=10/ZoomScale;for(int end=0;end<2;end++){var q=pts[end==0?0:pts.Length-1];if(Math.Abs(p.X-q.X)<=tolerance&&Math.Abs(p.Y-q.Y)<=tolerance){editingCable=selectedLink;editingEnd=true;endFrom=end==0;return true;}}for(int i=0;i<pts.Length-1;i++){var q=new PointF((pts[i].X+pts[i+1].X)/2,(pts[i].Y+pts[i+1].Y)/2);if(Math.Abs(p.X-q.X)<=tolerance&&Math.Abs(p.Y-q.Y)<=tolerance){editingCable=selectedLink;editingEnd=false;editingSegment=i;originalRoute=pts;return true;}}return false;}
 void DescribeLink(MapLink l){var a=Map.Nodes.First(n=>n.Id==l.From);var b=Map.Nodes.First(n=>n.Id==l.To);status(NodeName(a)+" ["+l.FromPort+"] → "+NodeName(b)+" ["+l.ToPort+"] · Drag square handles for path; round ends for port order.");}
 protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);Focus();if(locked)return;var p=World(e.Location);if(e.Button==MouseButtons.Left&&(ModifierKeys&Keys.Shift)==0&&CableHandle(p)){before=Map.Encode();dragOrigin=e.Location;Capture=true;return;}selected=Hit(p);selectedLink=selected==null?HitLink(p):null;if(selectedLink!=null)DescribeLink(selectedLink);Invalidate();if(e.Button==MouseButtons.Right){ShowMenu(e.Location);return;}if(e.Button!=MouseButtons.Left)return;last=e.Location;if(selected!=null&&ResizeHit(selected,p)){resizing=selected;offset=new PointF(p.X-selected.X-selected.Width,p.Y-selected.Y-selected.Height);before=Map.Encode();Capture=true;}else if(selected!=null&&SocketHit(selected,p)!=null){linkStart=selected;dragSide=SocketHit(selected,p);wire=p;Capture=true;}else if(selected!=null){moving=selected;offset=new PointF(p.X-moving.X,p.Y-moving.Y);before=Map.Encode();Capture=true;}else if(selectedLink==null){panning=true;Capture=true;}}
 protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);var p=World(e.Location);if(editingCable!=null){if(Math.Abs(e.X-dragOrigin.X)+Math.Abs(e.Y-dragOrigin.Y)<4)return;if(editingEnd){var n=Map.Nodes.First(x=>x.Id==(endFrom?editingCable.From:editingCable.To));MapRouting.ReorderEnd(Map,editingCable,endFrom,MapRouting.NearestSide(n,p),p);}else{bool horizontal=originalRoute[editingSegment].Y==originalRoute[editingSegment+1].Y;var adjusted=MapRouting.MoveSegment(originalRoute,editingSegment,horizontal?p.Y:p.X);if(adjusted.Count<=1000)editingCable.ManualRoute=adjusted;}Invalidate();}else if(resizing!=null){resizing.Width=Math.Max(178,Math.Min(2000,p.X-resizing.X-offset.X));resizing.Height=Math.Max(56,Math.Min(2000,p.Y-resizing.Y-offset.Y));Invalidate();}else if(moving!=null){moving.X=p.X-offset.X;moving.Y=p.Y-offset.Y;Invalidate();}else if(linkStart!=null){wire=p;Invalidate();}else if(panning){Pan=new PointF(Pan.X+e.X-last.X,Pan.Y+e.Y-last.Y);last=e.Location;Invalidate();}else{var n=Hit(p);Cursor=n!=null&&ResizeHit(n,p)?Cursors.SizeNWSE:Cursors.Default;}}
 protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);if(e.Button!=MouseButtons.Left)return;if(editingCable!=null){editingCable=null;Capture=false;if(Map.Encode()!=before){undo.Push(before);Save();}Invalidate();return;}var start=linkStart;var target=Hit(World(e.Location));linkStart=null;panning=false;Capture=false;if(moving!=null||resizing!=null){moving=null;resizing=null;if(Map.Encode()!=before){undo.Push(before);Save();}}if(start!=null&&target!=null&&start!=target){var l=new MapLink{From=start.Id,To=target.Id,FromSide=dragSide,ToSide=MapRouting.NearestSide(target,World(e.Location))};EditLink(l,true);}Invalidate();}
 protected override void OnMouseDoubleClick(MouseEventArgs e){base.OnMouseDoubleClick(e);if(locked)return;var n=Hit(World(e.Location));if(n!=null){var d=devices().FirstOrDefault(x=>x.Id==n.DeviceId);if(d!=null)open(d);}else{var l=HitLink(World(e.Location));if(l!=null)EditLink(l,false);}}
 void EditLink(MapLink l,bool add){using(var f=new LinkEditor(l,NodeName(Map.Nodes.First(n=>n.Id==l.From)),NodeName(Map.Nodes.First(n=>n.Id==l.To)))){if(f.ShowDialog(this)!=DialogResult.OK)return;Remember();l.FromPort=f.FromPort;l.ToPort=f.ToPort;l.Kind=f.Kind;if(add)Map.Links.Add(l);Save();}}
 void Remove(){if(locked)return;if(selected==null&&selectedLink==null)return;if(MessageBox.Show(this,"Remove the selected item from this layout? Device records are retained.","Remove from layout",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;Remember();if(selected!=null){Map.Links.RemoveAll(l=>l.From==selected.Id||l.To==selected.Id);Map.Nodes.Remove(selected);}else Map.Links.Remove(selectedLink);selected=null;selectedLink=null;Save();}
 void ShowMenu(Point p){while(menu.Items.Count>0){var old=menu.Items[0];menu.Items.RemoveAt(0);old.Dispose();}if(selected!=null){var d=devices().FirstOrDefault(x=>x.Id==selected.DeviceId);if(d!=null)menu.Items.Add("Device details",null,(s,e)=>open(d));menu.Items.Add("Reset tile size",null,(s,e)=>{Remember();selected.Width=178;selected.Height=56;Save();});menu.Items.Add("Remove from layout",null,(s,e)=>Remove());}else if(selectedLink!=null){var l=selectedLink;menu.Items.Add("Edit link / ports",null,(s,e)=>EditLink(l,false));menu.Items.Add("Reset path to automatic",null,(s,e)=>{Remember();l.ManualRoute.Clear();Save();});menu.Items.Add("Reset endpoints to automatic",null,(s,e)=>{Remember();l.FromSide=l.ToSide="";l.FromOrder=l.ToOrder=-1;Save();});menu.Items.Add("Remove link",null,(s,e)=>Remove());}else menu.Items.Add("Fit layout",null,(s,e)=>Fit());menu.Show(this,p);}
 protected override void OnKeyDown(KeyEventArgs e){base.OnKeyDown(e);if(e.KeyCode==Keys.Delete)Remove();if(e.Control&&e.KeyCode==Keys.Z){Undo();e.SuppressKeyPress=true;}if(e.KeyCode==Keys.Escape){if(moving!=null||resizing!=null||editingCable!=null){Map=NetworkMap.Decode(before);editingCable=null;selectedLink=null;moving=null;resizing=null;selected=null;}linkStart=null;panning=false;Capture=false;Invalidate();}}
 protected override void Dispose(bool disposing){if(disposing)menu.Dispose();base.Dispose(disposing);}
}
